// Daily Temperatures using Monotonic Stack
var stack = AnimatedStack<Int>()
let temps = [73, 74, 75, 71, 69, 72, 76]

func dailyTemperatures(_ temperatures: [Int], s: inout AnimatedStack<Int>) -> [Int] {
    var result = [Int](repeating: 0, count: temperatures.count)
    for i in 0..<temperatures.count {
        while !s.isEmpty {
            if let topIdx = s.peek(), temperatures[i] > temperatures[topIdx] {
                result[topIdx] = i - topIdx
                s.pop()
            } else {
                break
            }
        }
        s.push(i)
    }
    return result
}

let ans = dailyTemperatures(temps, s: &stack)
